from typing import Any

import httpx
from fastmcp.server import FastMCP


def build_mcp_server(
    openapi_spec: dict[str, Any],
    client: httpx.AsyncClient,
    name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """Build an MCP server whose tools mirror the operations of an OpenAPI spec.

    Args:
        openapi_spec: A minimal OpenAPI 3.0 specification as a dict.
        client: An httpx.AsyncClient already configured with the API base URL.
        name: Name to give the generated MCP server.

    Returns:
        A FastMCP server instance with tools generated from the OpenAPI spec.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


if __name__ == "__main__":
    openapi_spec: dict[str, Any] = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/items/{item_id}": {
                "get": {
                    "operationId": "get_item",
                    "summary": "Get an item by ID",
                    "parameters": [
                        {
                            "name": "item_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "integer"},
                        }
                    ],
                    "responses": {
                        "200": {
                            "description": "The requested item",
                            "content": {
                                "application/json": {
                                    "schema": {"type": "object"}
                                }
                            },
                        }
                    },
                }
            }
        },
    }

    api_client = httpx.AsyncClient(base_url="https://api.example.com")
    mcp = build_mcp_server(openapi_spec, api_client, name="Example API MCP Server")
